urlset:
  {{ site.base_url }}{{ generated }}
  {{ site.base_url }}updates/{{ generated }}
  {{ site.base_url }}methodology/{{ generated }}
  {{ site.base_url }}disclosure/{{ generated }}
{% for o in offers %}
